// The Brotli static dictionary that WOFF 2.0 needs (RFC 7932, Appendix A). It ships as a word list
// (vendor/brotli/dictionary.mjs, generated by tools/make-brotli-dictionary.mjs) and is loaded on the
// first WOFF 2.0 file only, so opening a .ttf or .otf never pays for it.

import { hasDictionary, setDictionary } from '../../vendor/brotli/brotli.mjs'

export const DICTIONARY_SIZE = 122784
export const DICTIONARY_SHA256 = '20e42eb1b511c21806d4d227d07e5dd06877d8ce7b3a817f378f313653f35c70'

/** log2 of the number of words of each length (RFC 7932, section 8). */
const SIZE_BITS = [0, 0, 0, 0, 10, 10, 11, 11, 10, 10, 10, 10, 10, 9, 9, 8, 7, 7, 8, 7, 7, 6, 6, 5, 5]

export type DictionaryWords = Readonly<Record<number, readonly (string | readonly number[])[]>>

/** The dictionary's bytes: every word of length 4, then of length 5, … up to 24. */
export function assembleDictionary(words: DictionaryWords): Uint8Array {
  const out = new Uint8Array(DICTIONARY_SIZE)
  const encoder = new TextEncoder()
  let at = 0
  for (let length = 4; length <= 24; length++) {
    const list = words[length] ?? []
    if (list.length !== 1 << SIZE_BITS[length]) {
      throw new Error(`the Brotli dictionary lists ${list.length} words of ${length} bytes, not ${1 << SIZE_BITS[length]}`)
    }
    for (const word of list) {
      const bytes = typeof word === 'string' ? encoder.encode(word) : Uint8Array.from(word)
      if (bytes.length !== length) {
        throw new Error(`a word of ${length} bytes in the Brotli dictionary has ${bytes.length}`)
      }
      out.set(bytes, at)
      at += length
    }
  }
  return out
}

let loading: Promise<void> | null = null

/** Whether WOFF 2.0 files can be opened now. */
export function brotliDictionaryLoaded(): boolean {
  return hasDictionary()
}

/** Loads the dictionary once; later calls share the first. A failed load can be tried again. */
export function loadBrotliDictionary(): Promise<void> {
  if (hasDictionary()) return Promise.resolve()
  loading ??= import('../../vendor/brotli/dictionary.mjs')
    .then((module) => setDictionary(assembleDictionary(module.WORDS_BY_LENGTH)))
    .catch((error: unknown) => {
      loading = null
      throw error
    })
  return loading
}
